char *kstrdup(const char *s, gfp_t gfp) /* <=== kstrdup */ 
{
	size_t len;
	char *buf;

	if (!s)
		return NULL;

	len = strlen(s) + 1;
	buf = kmalloc_track_caller(len, gfp);
	if (buf)
